' docs/architecture/order-components.puml: sơ đồ cập nhật trong cùng PR với code
@startuml
[API] <<..api..>>
[Domain] <<..domain..>>
[Persistence] <<..persistence..>>
[Payment] <<..payment..>>
[API] --> [Domain]
[Domain] --> [Persistence]
[Domain] --> [Payment]
@enduml

// Mọi class, mọi phụ thuộc trong com.shop.. đều phải có chỗ trên sơ đồ
@AnalyzeClasses(packages = "com.shop.order", importOptions = ImportOption.DoNotIncludeTests.class)
// class main @SpringBootApplication ở package gốc: cho vào một component, hoặc loại riêng
// bằng .that().resideOutsideOfPackage("com.shop.order")
@ArchTest
static final ArchRule matchesComponentDiagram = classes()
        .should(adhereToPlantUmlDiagram(
                Path.of("docs/architecture/order-components.puml"),
                consideringOnlyDependenciesInAnyPackage("com.shop..")));

// Chạy rule mới trên code cũ, ArchUnit báo 6 vi phạm (rút gọn tên package):
// Constructor <...api.OrderController.<init>(...OrderService, ...PspClient)> has parameter of type <...payment.PspClient>
// Constructor <...payment.PspClient.<init>(...OrderRepository)> has parameter of type <...persistence.OrderRepository>
// Field <...api.OrderController.pspClient> has type <...payment.PspClient>
// Field <...payment.PspClient.orderRepository> has type <...persistence.OrderRepository>
// Method <...api.OrderController.place(long)> calls method <...payment.PspClient.charge(long)> in (OrderController.java:16)
// Method <...payment.PspClient.charge(long)> calls method <...persistence.OrderRepository.save(long)> in (PspClient.java:14)

// Sửa code theo sơ đồ: Domain quyết định khi nào gọi thanh toán
public class OrderService {
    public String place(long orderId) {
        Order order = orderRepository.load(orderId);
        order.ensurePayable();                    // đơn đã huỷ thì dừng ở đây
        pspClient.charge(orderId);
        return orderRepository.save(order);
    }
}

public class OrderController {        // chỉ còn OrderService
    public String place(long orderId) {
        return orderService.place(orderId);
    }
}

public class PspClient {              // bỏ field OrderRepository
    public void charge(long orderId) {
        // ... chỉ gọi cổng thanh toán; Domain lo ghi dữ liệu
    }
}
